import json
import math
import statistics

dates = ["2025-03-03", "2025-03-04", "2025-03-05", "2025-03-06", "2025-03-07", "2025-03-10"]
closes = {
    "ACME": [182.5, 184.1, 183.2, 186.75, 185.9, 188.3],
    "BOLT": [41.2, 40.85, 41.6, 42.05, 41.3, 41.95],
}
tickers = sorted(closes)
prices = {"dates": dates, "tickers": tickers, "closes": closes}

rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()}
returns = {"base_date": dates[0], "dates": dates[1:], "tickers": tickers, "values": rets}
w = 2
vol = {}
for t, r in rets.items():
    v = []
    for i in range(len(r)):
        v.append(None if i < w else statistics.stdev(r[i - w : i]) * math.sqrt(252))
    vol[t] = v
volseries = {"returns": returns, "window": w, "annualized": True, "values": vol}

rawrows = []
for i, d in enumerate(dates[:4]):
    for t in tickers:
        c = closes[t][i]
        rawrows.append({"date": d, "ticker": t, "close": None if (t == "BOLT" and i == 2) else c})

r = rets["ACME"]
mu = statistics.mean(r) * 252
sd = statistics.stdev(r) * math.sqrt(252)
summary = {"ticker": "ACME", "ann_return": mu, "ann_vol": sd, "sharpe": mu / sd, "last_vol": vol["ACME"][-1]}

# drawdown for BOLT from closes
c = closes["BOLT"]
peak = c[0]
peak_d = dates[0]
best = (0.0, dates[0])
for d, x in zip(dates, c):
    if x > peak:
        peak, peak_d = x, d
    dd = x / peak - 1
    if dd < best[0]:
        best = (dd, peak_d)
drawdown = {"ticker": "BOLT", "depth": best[0], "peak_date": best[1]}

report = {
    "path": "out/risk_report.json",
    "rows": [
        {"ticker": "ACME", "ann_return": 1.2, "ann_vol": 0.21, "sharpe": 5.71, "last_vol": 0.3,
         "max_drawdown": -0.0046, "peak_date": "2025-03-06"},
        {"ticker": "BOLT", "ann_return": 0.4, "ann_vol": 0.25, "sharpe": 1.6, "last_vol": 0.4,
         "max_drawdown": -0.0178, "peak_date": "2025-03-06"},
    ],
}
for name, obj in [("prices", prices), ("returns", returns), ("vol", volseries), ("raw", rawrows),
                  ("summary", summary), ("dd", drawdown)]:
    print(name, json.dumps(obj))

import json
import math
import statistics
import sys
from pathlib import Path

out = Path(sys.argv[1])
dates = ["2024-01-02", "2024-01-03", "2024-01-04", "2024-01-05", "2024-01-08", "2024-01-09"]
closes = {
    "AAA": [100.0, 101.0, 99.5, 102.0, 103.5, 102.5],
    "BBB": [50.0, 50.5, 51.0, 51.25, 52.0, 52.5],
}
tickers = sorted(closes)
prices = {"dates": dates, "tickers": tickers, "closes": closes}

rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()}
returns = {"base_date": dates[0], "dates": dates[1:], "tickers": tickers, "values": rets}

w = 2
vol = {
    t: [None if i < w else statistics.stdev(r[i - w : i]) * math.sqrt(252) for i in range(len(r))]
    for t, r in rets.items()
}
volseries = {"returns": returns, "window": w, "annualized": True, "values": vol}


def summary(t):
    r = rets[t]
    ann_return = 252 * statistics.mean(r)
    ann_vol = math.sqrt(252) * statistics.stdev(r)
    return {
        "ticker": t,
        "ann_return": ann_return,
        "ann_vol": ann_vol,
        "sharpe": ann_return / ann_vol if ann_vol else 0.0,
        "last_vol": vol[t][-1],
    }


def drawdown(t):
    wealth, peak, peak_i = 1.0, 1.0, 0
    best = (0.0, 0, 0)
    seq = [1.0]
    for r in rets[t]:
        wealth *= math.exp(r)
        seq.append(wealth)
    for i, v in enumerate(seq):
        if v > peak:
            peak, peak_i = v, i
        d = v / peak - 1
        if d < best[0]:
            best = (d, peak_i, i)
    return {"ticker": t, "depth": best[0], "peak_date": dates[best[1]], "trough_date": dates[best[2]]}


rows = []
for t in tickers:
    s, d = summary(t), drawdown(t)
    rows.append({**s, "max_drawdown": d["depth"], "peak_date": d["peak_date"], "trough_date": d["trough_date"]})

raw = []
for i, d in enumerate(dates[:4]):
    for t in tickers:
        raw.append({"date": d, "ticker": t, "close": closes[t][i]})
raw[5]["close"] = None  # BBB on 2024-01-04: a blank cell

samples = {
    "mdata.RawRow": {"rows": raw},
    "mdata.Prices": prices,
    "risk.Returns": returns,
    "risk.VolSeries": volseries,
    "risk.TickerSummary": summary("AAA"),
    "risk.Drawdown": {"drawdowns": [drawdown("AAA"), drawdown("BBB")]},
    "risk.Report": {"path": "risk_report.json", "rows": rows},
}
for name, payload in samples.items():
    folder = out / name
    folder.mkdir(parents=True, exist_ok=True)
    (folder / "sample.json").write_text(json.dumps(payload, indent=1) + "\n")

csv = ["date,ticker,close"] + [f"{d},{t},{closes[t][i]}" for i, d in enumerate(dates) for t in tickers]
(out / "mdata.load_prices").mkdir(parents=True, exist_ok=True)
(out / "mdata.load_prices" / "prices.csv").write_text("\n".join(csv) + "\n")
(out / "risk.vol_series").mkdir(parents=True, exist_ok=True)
(out / "risk.vol_series" / "prices.csv").write_text("\n".join(csv) + "\n")

