def dd(t):
    seq=[1.0]
    for r in rets[t]: seq.append(seq[-1]*math.exp(r))
    peak,pi,best=1.0,0,(0.0,0,0)
    for i,v in enumerate(seq):
        if v>peak: peak,pi=v,i
        d=v/peak-1
        if d<best[0]: best=(d,pi,i)
    return dict(ticker=t,depth=best[0],peak_date=dates[best[1]],trough_date=dates[best[2]])
print(json.dumps(dict(rets=rets,vol=vol,summ=[summ('AAA'),summ('BBB')],dd=[dd('AAA'),dd('BBB')])))
